import asyncio
import hashlib
import hmac
import time
import json
from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, Optional, Set
from aiohttp import web
import aiohttp


class CircuitState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


@dataclass
class CircuitBreaker:
    failure_threshold: int = 5
    recovery_timeout: float = 30.0
    failure_count: int = 0
    last_failure_time: float = 0.0
    state: CircuitState = CircuitState.CLOSED

    def record_failure(self):
        self.failure_count += 1
        self.last_failure_time = time.time()
        if self.failure_count >= self.failure_threshold:
            self.state = CircuitState.OPEN

    def record_success(self):
        self.failure_count = 0
        self.state = CircuitState.CLOSED

    def can_execute(self) -> bool:
        if self.state == CircuitState.CLOSED:
            return True
        if self.state == CircuitState.OPEN:
            if time.time() - self.last_failure_time >= self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
                return True
            return False
        return True  # HALF_OPEN allows one attempt


@dataclass
class SessionContext:
    user_id: str
    origin: str
    authenticated_at: float
    permissions: Set[str] = field(default_factory=set)


class WebSocketService:
    def __init__(self, secret_key: str, allowed_origins: list):
        self.secret_key = secret_key
        self.allowed_origins = allowed_origins
        self.circuit_breaker = CircuitBreaker()
        self.active_sessions: Dict[str, SessionContext] = {}
        self.app = web.Application()
        self.app.router.add_get('/ws', self.websocket_handler)
        self.app.router.add_post('/api/token', self.issue_token)

    def _generate_token(self, user_id: str, timestamp: float) -> str:
        payload = f"{user_id}:{timestamp}"
        signature = hmac.new(
            self.secret_key.encode(),
            payload.encode(),
            hashlib.sha256
        ).hexdigest()
        return f"{payload}:{signature}"

    def _validate_token(self, token: str) -> Optional[str]:
        try:
            parts = token.split(':')
            if len(parts) != 3:
                return None
            user_id, timestamp_str, signature = parts
            timestamp = float(timestamp_str)
            if time.time() - timestamp > 3600:
                return None
            expected_payload = f"{user_id}:{timestamp_str}"
            expected_sig = hmac.new(
                self.secret_key.encode(),
                expected_payload.encode(),
                hashlib.sha256
            ).hexdigest()
            if hmac.compare_digest(signature, expected_sig):
                return user_id
            return None
        except (ValueError, IndexError):
            return None

    def _validate_origin(self, request: web.Request) -> bool:
        origin = request.headers.get('Origin', '')
        if not self.circuit_breaker.can_execute():
            return self._fallback_origin_check(origin)
        try:
            result = origin in self.allowed_origins
            if result:
                self.circuit_breaker.record_success()
            return result
        except Exception:
            self.circuit_breaker.record_failure()
            return self._fallback_origin_check(origin)

    def _fallback_origin_check(self, origin: str) -> bool:
        """Fallback when circuit is open - permissive to maintain availability"""
        return origin != ''

    async def _authenticate_websocket(self, request: web.Request) -> Optional[SessionContext]:
        token = request.query.get('token')
        if not token:
            auth_header = request.headers.get('Authorization', '')
            if auth_header.startswith('Bearer '):
                token = auth_header[7:]
        if not token:
            return None
        user_id = self._validate_token(token)
        if not user_id:
            return None
        origin = request.headers.get('Origin', 'unknown')
        return SessionContext(
            user_id=user_id,
            origin=origin,
            authenticated_at=time.time(),
            permissions={'read', 'write'}
        )

    async def websocket_handler(self, request: web.Request):
        if not self._validate_origin(request):
            return web.Response(status=403, text='Origin not allowed')

        session = await self._authenticate_websocket(request)
        if not session:
            return web.Response(status=401, text='Authentication required')

        ws = web.WebSocketResponse()
        await ws.prepare(request)

        self.active_sessions[session.user_id] = session

        try:
            async for msg in ws:
                if msg.type == aiohttp.WSMsgType.TEXT:
                    await self._handle_message(ws, session, msg.data)
                elif msg.type == aiohttp.WSMsgType.ERROR:
                    break
        finally:
            self.active_sessions.pop(session.user_id, None)

        return ws

    async def _handle_message(self, ws: web.WebSocketResponse, session: SessionContext, data: str):
        try:
            message = json.loads(data)
            action = message.get('action')
            if action == 'subscribe' and 'read' in session.permissions:
                await ws.send_json({'status': 'subscribed', 'channel': message.get('channel')})
            elif action == 'publish' and 'write' in session.permissions:
                await ws.send_json({'status': 'published', 'id': message.get('id')})
            else:
                await ws.send_json({'error': 'unauthorized_action'})
        except json.JSONDecodeError:
            await ws.send_json({'error': 'invalid_json'})

    async def issue_token(self, request: web.Request):
        body = await request.json()
        user_id = body.get('user_id')
        api_key = body.get('api_key')
        if not user_id or not api_key:
            return web.json_response({'error': 'missing_credentials'}, status=400)
        expected_key = hmac.new(
            self.secret_key.encode(),
            user_id.encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(api_key, expected_key):
            return web.json_response({'error': 'invalid_credentials'}, status=401)
        token = self._generate_token(user_id, time.time())
        return web.json_response({'token': token})


def create_app():
    import os
    secret = os.environ.get('WS_SECRET_KEY', 'default-secret-key-change-me')
    origins = os.environ.get('ALLOWED_ORIGINS', 'https://app.example.com').split(',')
    service = WebSocketService(secret_key=secret, allowed_origins=origins)
    return service.app


if __name__ == '__main__':
    app = create_app()
    web.run_app(app, host='0.0.0.0', port=8080)
